"""Plain-language definitions shared by widget and classic account rankings."""
HELP_PAGES = [
    ("Доступность данных", "Раньше — «полнота». Это доля весов категорий с известными уровнями и максимумами. Не процент прокачки! 100% означает, что для каждой категории нашлись данные, но не гарантирует полный состав войск. Нет данных — не ноль."),
    ("Что входит в оценку", "Осадные машины — таран, дирижабль и другие машины для атаки. Снаряжение — предметы героев, не сами герои. Войска и заклинания считаются отдельно. Цифры в карточке — добавленные баллы, не количество единиц."),
    ("Индекс и ратуша", "TH — уровень ратуши. Индекс: 10 × TH плюс до 9 баллов развития. Это не процент и он может быть больше 100. Например, TH18 даёт 180 баллов ещё до оценки армии. Звёзды КВ, донат и пропуски не входят."),
    ("Развитие и сравнение", "Уровни делятся на maxLevel из API: его максимум может не соответствовать вашей TH. Веса: герои 30%, войска 30%, заклинания 15%, осадные 10%, снаряжение 15%. Неизвестные категории исключены. Перцентиль — место среди соклановцев той же TH; 75 означает выше примерно 75% группы с учётом ничьих. Постройки не измеряются."),
]


def explanation_text():
    return "\n\n".join(title + "\n" + text for title, text in HELP_PAGES)
